    private void enableSpectrumFixture()throws Exception{org.robolectric.shadows.ShadowChoreographer.setPaused(true);Shadows.shadowOf((Application)RuntimeEnvironment.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);LauncherinAudioSpectrum.factory=()->new LauncherinAudioSpectrum.Capture(){public void start(int id,int rate,LauncherinAudioSpectrum.Listener listener){byte[] fft=new byte[512];for(int i=3;i<70;i++)fft[i*2]=(byte)(15+(i*7)%75);listener.fft(fft);}public void close(){}};LauncherinVisualOptions.save(activity,new LauncherinVisualOptions(new org.json.JSONObject().put("enabled",true)));call("reloadVisual");simulatedAudio();android.media.MediaPlayer p=new android.media.MediaPlayer();p.setAudioSessionId(73);Shadows.shadowOf(p).setState(org.robolectric.shadows.ShadowMediaPlayer.State.PREPARED);Shadows.shadowOf(p).setCurrentPosition(35000);ReflectionHelpers.setField(audio.get(),"player",p);ReflectionHelpers.setField(audio.get(),"prepared",true);measure();lifecycle.windowFocusChanged(true);ReflectionHelpers.setField(activity,"lastInteraction",SystemClock.elapsedRealtime());call("refresh");LauncherinCircularView rendered=field("heroVisual");for(int frame=0;frame<8;frame++)rendered.doFrame(SystemClock.elapsedRealtimeNanos()+frame*17000000L);rendered.cover.animate().cancel();rendered.cover.setAlpha(1f);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(100));}
    @Test public void realSpectrumFixtureDoesNotChangeLyricsAndPausesWhenScreenIsStopped()throws Exception{LauncherinAudioSpectrum.Factory before=LauncherinAudioSpectrum.factory;try{enableSpectrumFixture();LauncherinCircularView visual=field("heroVisual");assertTrue("id="+LauncherinPlayerService.audioSessionId()+" status="+visual.status()+" active="+field("active")+" shown="+visual.isShown()+" overlay="+field("visualScreen")+" saver="+field("saver")+" idle="+(SystemClock.elapsedRealtime()-(Long)field("lastInteraction"))+" focus="+activity.hasWindowFocus(),visual.real());assertTrue("cover must be visible",visual.cover.isShown());button("Letra").performClick();drainLyrics();assertTrue(((TextView)field("lyricsText")).getText().toString().contains("A letra acompanha"));activity.onBackPressed();lifecycle.pause().stop();assertFalse((Boolean)ReflectionHelpers.getField(visual,"scheduled"));lifecycle.start().resume().visible();}finally{LauncherinAudioSpectrum.factory=before;}}
    @Test public void intelligentProtectionDimsHidesMinimizesAndReturnsWithoutTriggeringPlay()throws Exception{LauncherinAudioSpectrum.Factory before=LauncherinAudioSpectrum.factory;try{enableSpectrumFixture();ReflectionHelpers.setField(activity,"lastInteraction",SystemClock.elapsedRealtime()-300001);call("refresh");assertTrue(((View)field("shell")).getAlpha()<1);ReflectionHelpers.setField(activity,"lastInteraction",SystemClock.elapsedRealtime()-900001);call("refresh");measure();Shadows.shadowOf(Looper.getMainLooper()).idle();assertNotNull(field("visualScreen"));assertEquals(View.GONE,((View)field("shell")).getVisibility());ReflectionHelpers.setField(activity,"lastInteraction",SystemClock.elapsedRealtime()-1800001);call("refresh");LauncherinCircularScreen screen=field("visualScreen");assertEquals(4,screen.circle.targetFps());activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));assertNull(field("visualScreen"));assertTrue(LauncherinPlayerService.playing());assertEquals(View.VISIBLE,((View)field("shell")).getVisibility());assertEquals(1,((View)field("shell")).getAlpha(),.001);}finally{LauncherinAudioSpectrum.factory=before;}}
