    private void drainImages()throws Exception{LauncherinMusicArtwork image=field("images");java.util.concurrent.ExecutorService worker=ReflectionHelpers.getField(image,"worker");for(int i=0;i<4;i++){worker.submit(()->{}).get(2,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}}
    private void photoFixture()throws Exception{File dir=Config.dir(activity);if(dir==null)dir=activity.getFilesDir();dir.mkdirs();String id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";File image=new File(dir,"frame-"+id.substring(0,40)+".jpg");try(OutputStream out=new FileOutputStream(image)){art(3,960,540).compress(Bitmap.CompressFormat.JPEG,85,out);}org.json.JSONObject data=LauncherinExtras.read(activity);data.put("frame_photos",new org.json.JSONArray().put(id));try(OutputStream out=new FileOutputStream(new File(dir,"config.json"))){out.write(data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
    private Bitmap art(int n,int width,int height){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.RGB_565);Canvas c=new Canvas(b);Paint p=new Paint(3);int[] top={0xff865d36,0xff223552,0xff163c46,0xff355c4c,0xff674855,0xff39324f};p.setShader(new LinearGradient(0,0,width,height,new int[]{top[n%6],0xff07161c},null,Shader.TileMode.CLAMP));c.drawRect(0,0,width,height,p);p.setShader(null);p.setColor(n%2==0?0xffd4ac75:0xff9bafbb);c.drawCircle(width*.65f,height*.32f,width*.17f,p);p.setColor(0xff17363c);Path hill=new Path();hill.moveTo(0,height*.8f);hill.cubicTo(width*.3f,height*.25f,width*.55f,height,width,height*.45f);hill.lineTo(width,height);hill.lineTo(0,height);c.drawPath(hill,p);p.setColor(0xff0b252b);hill.reset();hill.moveTo(0,height*.85f);hill.cubicTo(width*.4f,height,width*.65f,height*.4f,width,height*.76f);hill.lineTo(width,height);hill.lineTo(0,height);c.drawPath(hill,p);return b;}

