    @Test public void profilePhotoAndFullscreenVisualizerKeepThePlayerAndFocus()throws Exception{
        LauncherinMusicProfiles profiles=new LauncherinMusicProfiles(activity);LauncherinMusicProfiles.Profile old=profiles.active();ByteArrayOutputStream jpeg=new ByteArrayOutputStream();Bitmap pic=art(4,256,256);pic.compress(Bitmap.CompressFormat.JPEG,85,jpeg);pic.recycle();byte[] bytes=jpeg.toByteArray();String hash=LauncherinMusicLibrary.hash(bytes);
        try(FileOutputStream out=new FileOutputStream(LauncherinProfilePhotos.incoming(activity,"mp-"+hash.substring(0,40)+".jpg"))){out.write(bytes);}
        byte[] metadata=new org.json.JSONObject().put("id",old.id).put("name","Perfil de exemplo").put("photo",hash).put("expected",LauncherinProfilePhotos.revision(old)).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(LauncherinProfilePhotos.incoming(activity,LauncherinProfilePhotos.PENDING))){out.write(metadata);}
        assertTrue(LauncherinProfilePhotos.call(activity,"commitMusicProfile",LauncherinMusicLibrary.hash(metadata)).getBoolean("ok"));call("refresh");assertNotNull(((ImageView)field("profilePhoto")).getDrawable());assertEquals("",((TextView)field("profileButton")).getText().toString());measure();ImageView avatar=field("profilePhoto");Bitmap renderedAvatar=Bitmap.createBitmap(avatar.getWidth(),avatar.getHeight(),Bitmap.Config.ARGB_8888);avatar.draw(new Canvas(renderedAvatar));int center=renderedAvatar.getPixel(renderedAvatar.getWidth()/2,renderedAvatar.getHeight()/2);assertTrue("Profile photo must be painted in the header",Color.alpha(center)>240);assertNotEquals("The avatar must not be an empty colored badge",0xff9273c8,center);renderedAvatar.recycle();save("music-profile-header");call("profiles");Shadows.shadowOf(Looper.getMainLooper()).idle();save("music-profile-photo-menu");ShadowAlertDialog.getLatestAlertDialog().dismiss();
        LauncherinAudioSpectrum.Factory before=LauncherinAudioSpectrum.factory;try{enableSpectrumFixture();View play=field("heroPlay");focuses().get("hero-visual").performClick();measure();Shadows.shadowOf(Looper.getMainLooper()).idle();call("refresh");measure();LauncherinCircularScreen screen=field("visualScreen");assertNotNull(screen);assertEquals(View.GONE,((View)field("shell")).getVisibility());assertTrue(screen.circle.getLayoutParams().width>450);for(int i=0;i<8;i++)screen.circle.doFrame(SystemClock.elapsedRealtimeNanos()+i*17000000L);screen.circle.cover.animate().cancel();screen.circle.cover.setAlpha(1f);drainImages();measure();assertTrue("cover-size="+screen.circle.cover.getWidth()+"x"+screen.circle.cover.getHeight(),screen.circle.cover.getWidth()>200);assertNotNull("fullscreen cover must keep its artwork",screen.circle.cover.getDrawable());
        assertEquals("The album drawable must stay fully opaque",255,screen.circle.cover.getDrawable().getAlpha());save("music-fullscreen-spectrum-fixture");activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK));activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK));assertNull(field("visualScreen"));assertTrue(LauncherinPlayerService.playing());assertSame(play,field("heroPlay"));assertTrue(play.hasFocus());}finally{LauncherinAudioSpectrum.factory=before;}
    }
