    private void save(String name)throws Exception{measure();drainImages();View view=activity.findViewById(android.R.id.content);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);view.draw(c);AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();if(dialog!=null&&dialog.isShowing()){View decor=dialog.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(680,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(480,View.MeasureSpec.AT_MOST));decor.layout(0,0,decor.getMeasuredWidth(),decor.getMeasuredHeight());c.drawColor(0x88000000);int layer=c.save();c.translate((960-decor.getMeasuredWidth())/2f,(540-decor.getMeasuredHeight())/2f);decor.draw(c);c.restoreToCount(layer);}Paint p=new Paint(3);p.setColor(0xffa6b7c8);p.setTextSize(8);c.drawText(name.contains("fixture")?"PRÉVIA LOCAL · FFT SINTÉTICO DE TESTE · ARTES DE EXEMPLO":"PRÉVIA LOCAL · COMPONENTES ANDROID · MÚSICAS E ARTES DE EXEMPLO",24,534,p);File dir=new File("/tmp/launcherin25/captures");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
